<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
const topic=ref('')
const data=ref(null),error=ref(''),editing=ref(null),offset=ref(0),form=ref({name:'',position:0,frequency:'daily',weekdays:[],enabled:true,removed:false}),writes=useWorkflowWrite('care-settings')
async function load(){try{data.value=await api.flow('/care?offset='+offset.value)}catch(e){error.value=e.message}}
async function act(path,body,method='PUT'){try{await writes.send(path,body,method);await load();error.value=''}catch(e){error.value=e.message}}
async function save(){await act('/care/items'+(editing.value?'/'+editing.value.id:''),{...form.value,expected_version:editing.value?.version||0},editing.value?'PUT':'POST');if(!error.value){editing.value=null;form.value={name:'',position:0,frequency:'daily',weekdays:[],enabled:true,removed:false}}}
function edit(row){editing.value=row;form.value={name:row.name,position:row.position,...row.rule,enabled:row.enabled,removed:row.removed}}
onMounted(load)
</script>
<template><div class="reading-page"><PageHeader title="照顾自己设置" description="关注哪些事、放几个项目，都由你决定。"/><p v-if="error" class="error">{{ error }}</p><section v-if="data" class="card"><button class="btn" @click="act('/care/config',{expected_version:data.config?.version||0,enabled:!data.config?.enabled,initialize_examples:false,ai_allowed:!!data.config?.ai_allowed})">{{ data.config?.enabled?'关闭首页清单':'开启首页清单' }}</button><button v-if="!data.config" class="btn" @click="act('/care/config',{expected_version:0,enabled:true,initialize_examples:true})">采用睡眠、饮食、活动示例（可删改）</button><label><input type="checkbox" :checked="!!data.config?.ai_allowed" @change="e=>act('/care/config',{expected_version:data.config?.version||0,enabled:data.config?.enabled??true,ai_allowed:e.target.checked})"/>允许回顾参考当前关注项目名称与安排（记录正文仍逐篇许可）</label><p class="muted">零项或当天无安排时，首页隐藏；移除保留历史，不自动重建默认项。</p></section><section class="card"><h2>可选项目建议</h2><label>主动告诉 AI 想关注的方向<textarea v-model="topic" maxlength="2000"/></label><button class="btn" :disabled="writes.busy.value" @click="act('/care/suggestions',{topic,expected_version:data?.config?.version||0},'POST')">仅请求候选，不自动添加</button><article v-for="(suggestion,n) in data?.config?.suggestions||[]" :key="n"><p>{{ suggestion.name }} · {{ suggestion.state==='accepted'?'已添加':'候选' }}</p><button v-if="suggestion.state==='suggested'" class="btn" :disabled="writes.busy.value" @click="act('/care/suggestions/'+n+'/accept',{expected_version:data.config.version},'POST')">接受并添加</button></article></section><form class="card" @submit.prevent="save"><h2>{{ editing?'修改项目':'添加项目' }}</h2><label>名称<input v-model="form.name" maxlength="80" required/></label><label>排序<input type="number" min="0" v-model.number="form.position"/></label><label>安排<select v-model="form.frequency"><option value="daily">每天</option><option value="weekdays">指定星期</option><option value="manual">自行安排（仅管理页）</option></select></label><div v-if="form.frequency==='weekdays'"><label v-for="(name,n) in ['一','二','三','四','五','六','日']" :key="n"><input type="checkbox" v-model="form.weekdays" :value="n"/>周{{ name }}</label></div><label><input type="checkbox" v-model="form.enabled"/>启用</label><button class="btn primary" :disabled="writes.busy.value">保存项目</button></form><section class="card"><article v-for="item in data?.items" :key="item.id"><h3>{{ item.name }} · {{ item.enabled?'启用':'停用' }}</h3><button class="btn" @click="edit(item)">改名 / 排序 / 安排</button><button class="btn" :disabled="writes.busy.value" @click="act('/care/items/'+item.id,{name:item.name,position:item.position,...item.rule,enabled:false,removed:true,expected_version:item.version})">移除，保留历史</button></article><button class="btn" v-if="offset>0" @click="offset=Math.max(0,offset-100);load()">上一页</button><button class="btn" v-if="data?.items.length===100" @click="offset+=100;load()">下一页</button></section><details v-if="data?.legacy_history?.length"><summary>采用旧清单的项目和状态</summary><article v-for="legacy in data.legacy_history" :key="legacy.id"><p>{{ legacy.local_date }} · {{ Object.keys(legacy.payload.entries||{}).join('、') }}</p><button class="btn" :disabled="writes.busy.value" @click="act('/care/legacy-import',{legacy_id:legacy.id,legacy_version:legacy.version,expected_version:data.config?.version||0},'POST')">映射此日旧项目，保留原 JSON</button></article><p class="muted">只映射项目和状态，不猜测原文关联，不生成事件或奖励；重复映射不复制历史。</p></details><details v-if="data?.legacy"><summary>此日旧清单（保留原记录）</summary><p v-for="(value,key) in data.legacy.payload.entries" :key="key">{{ key }} · {{ value }}</p></details></div></template>
